:root {
  color-scheme: light;
  --canvas: var(--sya-canvas, #eef1ed);
  --surface: var(--sya-surface, #fcfdfb);
  --surface-muted: var(--sya-surface-muted, #e2e6e1);
  --text: var(--sya-text, #191b19);
  --text-secondary: var(--sya-text-secondary, #59605b);
  --border: var(--sya-border, #d9ddd9);
  --primary: var(--sya-primary, #252725);
  --primary-hover: var(--sya-primary-hover, #343734);
  --primary-foreground: var(--sya-primary-foreground, #f8faf8);
  --success: var(--sya-success, #18794e);
  --success-foreground: var(--sya-success-foreground, #ffffff);
  --success-surface: var(--sya-success-surface, #e7f6ec);
  --success-surface-foreground: var(--sya-success-surface-foreground, #17653f);
  --warning: var(--sya-warning, #946200);
  --warning-foreground: var(--sya-warning-foreground, #ffffff);
  --warning-surface: var(--sya-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #6b4600);
  --danger: var(--sya-danger, #b42318);
  --danger-foreground: var(--sya-danger-foreground, #ffffff);
  --danger-surface: var(--sya-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #8f1d14);
  --focus: var(--sya-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--sya-canvas, #121412);
    --surface: var(--sya-surface, #1a1d1a);
    --surface-muted: var(--sya-surface-muted, #232623);
    --text: var(--sya-text, #f1f3f0);
    --text-secondary: var(--sya-text-secondary, #afb5b0);
    --border: var(--sya-border, #373b37);
    --primary: var(--sya-primary, #ecefeb);
    --primary-hover: var(--sya-primary-hover, #ffffff);
    --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
    --success: var(--sya-success, #62c98f);
    --success-foreground: var(--sya-success-foreground, #092416);
    --success-surface: var(--sya-success-surface, #173526);
    --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
    --warning: var(--sya-warning, #e9ad45);
    --warning-foreground: var(--sya-warning-foreground, #291900);
    --warning-surface: var(--sya-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
    --danger: var(--sya-danger, #ff716b);
    --danger-foreground: var(--sya-danger-foreground, #260503);
    --danger-surface: var(--sya-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
    --focus: var(--sya-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--sya-canvas, #121412);
  --surface: var(--sya-surface, #1a1d1a);
  --surface-muted: var(--sya-surface-muted, #232623);
  --text: var(--sya-text, #f1f3f0);
  --text-secondary: var(--sya-text-secondary, #afb5b0);
  --border: var(--sya-border, #373b37);
  --primary: var(--sya-primary, #ecefeb);
  --primary-hover: var(--sya-primary-hover, #ffffff);
  --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
  --success: var(--sya-success, #62c98f);
  --success-foreground: var(--sya-success-foreground, #092416);
  --success-surface: var(--sya-success-surface, #173526);
  --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
  --warning: var(--sya-warning, #e9ad45);
  --warning-foreground: var(--sya-warning-foreground, #291900);
  --warning-surface: var(--sya-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
  --danger: var(--sya-danger, #ff716b);
  --danger-foreground: var(--sya-danger-foreground, #260503);
  --danger-surface: var(--sya-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
  --focus: var(--sya-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .sya-code-source .shiki,
html[data-theme="dark"] .sya-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .sya-code-source .shiki,
  html:not([data-theme="light"]) .sya-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes sya-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes sya-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes sya-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface TabsItem {
  value: string;
  label: string;
  icon?: ReactNode;
  content: ReactNode;
}

export interface TabsProps {
  items: TabsItem[];
  value?: string;
  defaultValue?: string;
  variant?: "flat" | "grouped";
  ariaLabel?: string;
  className?: string;
  listClassName?: string;
  panelClassName?: string;
  animatePanelHeight?: boolean;
  onValueChange?: (value: string) => void;
}

export function Tabs({
  items,
  value,
  defaultValue,
  variant = "flat",
  ariaLabel = "Tabs",
  className,
  listClassName,
  panelClassName,
  animatePanelHeight = false,
  onValueChange,
}: TabsProps) {
  const id = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const listRef = useRef<HTMLDivElement>(null);
  const tabRefs = useRef(new Map<string, HTMLButtonElement>());
  const indicatorReady = useRef(false);
  const panelRef = useRef<HTMLDivElement>(null);
  const panelContentRef = useRef<HTMLDivElement>(null);
  const panelMeasured = useRef(false);
  const [internalValue, setInternalValue] = useState(
    defaultValue ?? items[0]?.value ?? "",
  );
  const fallbackValue = items[0]?.value ?? "";
  const requestedValue = value ?? internalValue;
  const activeValue = items.some((item) => item.value === requestedValue)
    ? requestedValue
    : fallbackValue;
  const activeItem = items.find((item) => item.value === activeValue);
  const indicatorX = useMotionValue(0);
  const indicatorY = useMotionValue(0);
  const indicatorWidth = useMotionValue(0);
  const indicatorHeight = useMotionValue(0);
  const indicatorOpacity = useMotionValue(0);
  const panelHeight = useMotionValue<number | string>("auto");

  const select = (nextValue: string) => {
    if (value === undefined) setInternalValue(nextValue);
    onValueChange?.(nextValue);
  };

  const moveFocus = (
    event: KeyboardEvent<HTMLButtonElement>,
    currentIndex: number,
  ) => {
    let nextIndex = currentIndex;

    if (event.key === "ArrowRight") nextIndex = (currentIndex + 1) % items.length;
    else if (event.key === "ArrowLeft") {
      nextIndex = (currentIndex - 1 + items.length) % items.length;
    } else if (event.key === "Home") nextIndex = 0;
    else if (event.key === "End") nextIndex = items.length - 1;
    else return;

    event.preventDefault();
    const nextValue = items[nextIndex]?.value;
    if (!nextValue) return;
    select(nextValue);
    tabRefs.current.get(nextValue)?.focus();
  };

  useLayoutEffect(() => {
    const list = listRef.current;
    const tab = tabRefs.current.get(activeValue);

    if (!list || !tab) {
      indicatorReady.current = false;
      indicatorOpacity.jump(0);
      return;
    }

    const listRect = list.getBoundingClientRect();
    const tabRect = tab.getBoundingClientRect();
    const nextX = tabRect.left - listRect.left;
    const nextY = tabRect.top - listRect.top;
    const transition = reduceMotion
      ? { duration: 0 }
      : motionTokens.spring.morph;

    if (!indicatorReady.current || reduceMotion) {
      indicatorX.jump(nextX);
      indicatorY.jump(nextY);
      indicatorWidth.jump(tabRect.width);
      indicatorHeight.jump(tabRect.height);
    } else {
      animate(indicatorX, nextX, transition);
      animate(indicatorY, nextY, transition);
      animate(indicatorWidth, tabRect.width, transition);
      animate(indicatorHeight, tabRect.height, transition);
    }

    indicatorReady.current = true;
    indicatorOpacity.jump(1);
  }, [activeValue, indicatorHeight, indicatorOpacity, indicatorWidth, indicatorX, indicatorY, items, reduceMotion, variant]);

  useLayoutEffect(() => {
    if (!animatePanelHeight) return;
    const panel = panelRef.current;
    const content = panelContentRef.current;
    if (!panel || !content) return;
    let stopAnimation = () => {};

    const measure = () => {
      const computed = getComputedStyle(panel);
      const verticalChrome =
        parseFloat(computed.paddingTop) +
        parseFloat(computed.paddingBottom) +
        parseFloat(computed.borderTopWidth) +
        parseFloat(computed.borderBottomWidth);
      const nextHeight = content.getBoundingClientRect().height + verticalChrome;
      stopAnimation();

      if (!panelMeasured.current || reduceMotion) {
        panelMeasured.current = true;
        panelHeight.jump(nextHeight);
        return;
      }

      const controls = animate(
        panelHeight,
        nextHeight,
        motionTokens.spring.smooth,
      );
      stopAnimation = () => controls.stop();
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(content);

    return () => {
      observer.disconnect();
      stopAnimation();
    };
  }, [activeValue, animatePanelHeight, panelHeight, reduceMotion]);

  if (!items.length || !activeItem) return null;

  const activeIndex = items.findIndex((item) => item.value === activeValue);

  return (
    <div className={["min-w-0", className].filter(Boolean).join(" ")}>
      <div
        ref={listRef}
        className={[
          variant === "grouped" ? "relative flex w-fit max-w-full gap-0.5 overflow-x-auto rounded-[10px] border border-[var(--border)] bg-[var(--surface-muted)] p-[3px]" : "relative flex max-w-full gap-1 overflow-x-auto border-b border-[var(--border)]",
          listClassName,
        ]
          .filter(Boolean)
          .join(" ")}
        role="tablist"
        aria-label={ariaLabel}
      >
        <motion.span
          className={
            variant === "grouped"
              ? "pointer-events-none absolute top-0 left-0 rounded-[7px] bg-[var(--surface)] shadow-[0_1px_2px_rgb(20_28_23_/_8%)]"
              : "pointer-events-none absolute bottom-0 left-0 h-0.5 rounded-t-full bg-[var(--text)]"
          }
          style={{
            x: indicatorX,
            y: variant === "grouped" ? indicatorY : 0,
            width: indicatorWidth,
            height: variant === "grouped" ? indicatorHeight : undefined,
            opacity: indicatorOpacity,
          }}
          aria-hidden="true"
        />
        {items.map((item, index) => {
          const active = item.value === activeValue;

          return (
            <button
              ref={(element) => {
                if (element) tabRefs.current.set(item.value, element);
                else tabRefs.current.delete(item.value);
              }}
              className={["relative z-[1] inline-flex min-h-9 shrink-0 items-center justify-center gap-[7px] rounded-[7px] border-0 bg-transparent px-3 text-[13px] leading-none font-[560] whitespace-nowrap text-[var(--text-secondary)] transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] hover:text-[var(--text)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-2", active && "text-[var(--text)]"].filter(Boolean).join(" ")}
              id={`${id}-tab-${index}`}
              role="tab"
              type="button"
              tabIndex={active ? 0 : -1}
              aria-selected={active}
              aria-controls={`${id}-panel-${index}`}
              onClick={() => select(item.value)}
              onKeyDown={(event) => moveFocus(event, index)}
              key={item.value}
            >
              {item.icon ? (
                <span className="inline-flex shrink-0" aria-hidden="true">
                  {item.icon}
                </span>
              ) : null}
              <span>{item.label}</span>
            </button>
          );
        })}
      </div>
      <motion.div
        ref={panelRef}
        className={[
          "min-w-0 pt-[18px] outline-none focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-2",
          animatePanelHeight ? "overflow-hidden" : undefined,
          panelClassName,
        ]
          .filter(Boolean)
          .join(" ")}
        id={`${id}-panel-${activeIndex}`}
        role="tabpanel"
        aria-labelledby={`${id}-tab-${activeIndex}`}
        tabIndex={0}
        style={{ height: animatePanelHeight ? panelHeight : undefined }}
      >
        <div ref={panelContentRef}>{activeItem.content}</div>
      </motion.div>
    </div>
  );
}
